opentelemetry_sdk = { version = "0.33.1", features = ["rt-tokio", "metrics"] }
opentelemetry-otlp = { version = "0.33.1", default-features = false, features = ["http-proto", "metrics", "reqwest-blocking-client"] }
tracing = "0.1.44"
tracing-opentelemetry = "0.34.0"
tracing-subscriber = "0.3"

use serde::{Deserialize, Serialize};

#[derive(Serialize, Deserialize, Debug)]
pub struct Probe {
    pub id: u64,
}

pub fn open_mem_db() -> rusqlite::Result<rusqlite::Connection> {
    rusqlite::Connection::open_in_memory()
}

pub fn watcher() -> notify::Result<notify::RecommendedWatcher> {
    use notify::Watcher;
    notify::RecommendedWatcher::new(|_e| {}, notify::Config::default())
}

pub fn keyring_entry() -> keyring_core::Result<keyring_core::Entry> {
    #[cfg(target_os = "macos")]
    keyring_core::set_default_store(apple_native_keyring_store::keychain::Store::new()?);
    keyring_core::Entry::new("droid-observatory/readiness-probe", "probe")
}

pub fn otlp_exporter() -> Result<opentelemetry_otlp::MetricExporter, opentelemetry_otlp::ExporterBuildError> {
    use opentelemetry_otlp::WithExportConfig;
    opentelemetry_otlp::MetricExporter::builder()
        .with_http()
        .with_protocol(opentelemetry_otlp::Protocol::HttpBinary)
        .with_endpoint("https://otlp-gateway-prod-eu-west-2.grafana.net/otlp/v1/metrics")
        .build()
}

pub fn rt() -> std::io::Result<tokio::runtime::Runtime> {
    tokio::runtime::Builder::new_multi_thread().enable_all().build()
}

pub fn span() {
    let _layer = tracing_opentelemetry::layer::<tracing_subscriber::Registry>();
    tracing::info!("probe");
}

